// 홈 화면: 앱 소개, 간단한 미리보기
function Home() {
  return (
    <div style={{ padding: "20px" }}>
      <h1>✨ SNS 리뷰 플랫폼</h1>
      <p>화장품 · 패션 · 생활용품 리뷰를 공유하는 커뮤니티입니다.</p>

      <h2>🔥 인기 리뷰</h2>
      <p>여기엔 나중에 실제 서버 데이터가 들어가요.</p>

      <h2>📰 AI 요약 매거진</h2>
      <p>리뷰 여러 개를 AI가 잡지처럼 자동 요약합니다.</p>
    </div>
  );
}

export default Home;
